use molbiocraft_core::{
    FeatureSegment, HistoryTreeNode, MoleculeType, SequenceDocument, SequenceFeature, Topology,
};
use std::collections::HashMap;

/// When MolBioCraft sourced the records re-sourced by US-01M6TDFV, as
/// `sample_library_data.rs` records it.
use crate::sample_library_data::SOURCED_ON;

fn make_meta(entries: &[(&str, serde_json::Value)]) -> HashMap<String, serde_json::Value> {
    entries
        .iter()
        .map(|(k, v)| ((*k).to_string(), v.clone()))
        .collect()
}

fn make_qualifiers(entries: &[(&str, &str)]) -> Option<HashMap<String, String>> {
    if entries.is_empty() {
        None
    } else {
        Some(
            entries
                .iter()
                .map(|(k, v)| ((*k).to_string(), (*v).to_string()))
                .collect(),
        )
    }
}

#[allow(clippy::too_many_arguments)]
fn make_genome_feat(
    id: &str,
    name: &str,
    feature_type: &str,
    start: usize,
    end: usize,
    strand: i8,
    color: &str,
    notes: Option<&str>,
    qualifiers: Option<HashMap<String, String>>,
) -> SequenceFeature {
    SequenceFeature {
        id: id.to_string(),
        name: name.to_string(),
        feature_type: feature_type.to_string(),
        start,
        end,
        strand,
        color: color.to_string(),
        notes: notes.map(|s| s.to_string()),
        qualifiers,
        segments: None,
        cleavage_site: None,
    }
}

/// Reference genome sample documents, normalized so that every coordinate is a real one:
///
/// * Multi-interval NCBI features (`join`/`order`, recorded as `intervals_summary`) carry explicit
///   segments in transcript order, so spliced, frameshifted and trans-spliced genes are drawn and
///   translated correctly.
/// * Contig-summary records (no downloaded bases) keep an empty sequence and their annotations at
///   true genomic coordinates on the declared chromosome length.
pub fn get_genome_sample_documents() -> Vec<SequenceDocument> {
    raw_genome_sample_documents()
        .into_iter()
        .map(normalize_reference_record)
        .collect()
}

/// Parses an `intervals_summary` qualifier such as `"336..1637, 1637..4642"` (transcript order).
pub fn parse_intervals_summary(summary: &str) -> Vec<(usize, usize)> {
    summary
        .split(',')
        .filter_map(|part| {
            let mut it = part.trim().split("..");
            let a = it.next()?.trim().replace(',', "").parse::<usize>().ok()?;
            let b = it.next()?.trim().replace(',', "").parse::<usize>().ok()?;
            Some((a.min(b), a.max(b)))
        })
        .collect()
}

fn qualifier_usize(f: &SequenceFeature, key: &str) -> Option<usize> {
    f.qualifiers
        .as_ref()?
        .get(key)?
        .replace(',', "")
        .trim()
        .parse::<usize>()
        .ok()
}

fn declared_length(doc: &SequenceDocument) -> usize {
    doc.doc_metadata
        .as_ref()
        .and_then(|m| m.get("Declared Length"))
        .and_then(|v| {
            v.as_u64()
                .map(|n| n as usize)
                .or_else(|| v.as_str().and_then(|s| s.replace(',', "").parse().ok()))
        })
        .unwrap_or(0)
}

/// Applies the coordinate and summary invariants described on [`get_genome_sample_documents`].
pub fn normalize_reference_record(mut doc: SequenceDocument) -> SequenceDocument {
    let declared = declared_length(&doc);
    let is_summary = doc.sequence.is_empty() && declared > 0;
    // Derive the annotation tally rather than carrying it as a literal, so the Info panel and the
    // workbench column can never disagree with the annotations the record actually ships.
    let annotation_count = doc.features.len();
    doc.doc_metadata
        .get_or_insert_with(HashMap::new)
        .insert("Annotations Count".into(), serde_json::json!(annotation_count));
    if is_summary {
        let meta = doc.doc_metadata.get_or_insert_with(HashMap::new);
        meta.insert("Is Contig Summary".into(), serde_json::json!(true));
        for h in &mut doc.history {
            h.length_bp = declared;
        }
    }
    for f in &mut doc.features {
        let intervals = f
            .qualifiers
            .as_ref()
            .and_then(|q| q.get("intervals_summary"))
            .map(|s| parse_intervals_summary(s))
            .unwrap_or_default();
        if is_summary {
            // Annotations were stored rescaled onto a placeholder; restore genomic coordinates.
            if let (Some(gs), Some(ge)) = (
                qualifier_usize(f, "genomic_start"),
                qualifier_usize(f, "genomic_end"),
            ) {
                f.start = gs.min(ge).max(1);
                f.end = gs.max(ge).min(declared.max(1));
            }
        }
        if intervals.len() > 1 && f.segments.is_none() {
            f.start = intervals.iter().map(|iv| iv.0).min().unwrap_or(f.start);
            f.end = intervals.iter().map(|iv| iv.1).max().unwrap_or(f.end);
            f.segments = Some(
                intervals
                    .iter()
                    .enumerate()
                    .map(|(i, &(a, b))| FeatureSegment {
                        index: i + 1,
                        name: format!("{} part {}", f.name, i + 1),
                        start: a,
                        end: b,
                        color: f.color.clone(),
                    })
                    .collect(),
            );
        }
    }
    doc
}

